            // Wait for DOM to be ready
            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', init);
            } else {
                init();
            }

            function init() {
                addReviewLink();
                handleAnchorScrolling();
            }

            function addReviewLink() {
                var productDiv = document.querySelector('div[id^="product-"]');
                if (!productDiv) return;

                var ratingSection = productDiv.querySelector('.woocommerce-product-rating');
                if (!ratingSection) return;

                // Check if link already exists
                if (ratingSection.querySelector('.woocommerce-review-link')) return;

                // Get review count from star rating
                var starRating = ratingSection.querySelector('.star-rating span');
                if (!starRating) return;

                var ratingText = starRating.textContent;
                var countMatch = ratingText.match(/based on (\d+) customer rating/);

                if (countMatch) {
                    var count = parseInt(countMatch[1]);
                    var reviewText = count === 1 ? 'customer review' : 'customer reviews';

                    // Create review link
                    var link = document.createElement('a');
                    link.href = '#reviews';
                    link.className = 'woocommerce-review-link';
                    link.textContent = '(' + count + ' ' + reviewText + ')';

                    // Add click handler to scroll to reviews
                    link.addEventListener('click', function(e) {
                        e.preventDefault();
                        scrollToSection('reviews');
                    });

                    // Append link to rating section
                    ratingSection.appendChild(link);
                }
            }

            function handleAnchorScrolling() {
                // Handle hash in URL on page load
                if (window.location.hash) {
                    var hash = window.location.hash.substring(1);
                    if (hash === 'reviews' || hash === 'q-a') {
                        setTimeout(function() {
                            scrollToSection(hash);
                        }, 100);
                    }
                }

                // Handle hash changes
                window.addEventListener('hashchange', function() {
                    var hash = window.location.hash.substring(1);
                    if (hash === 'reviews' || hash === 'q-a') {
                        scrollToSection(hash);
                    }
                });
            }

            function scrollToSection(sectionClass) {
                var section = document.querySelector('.' + sectionClass);
                if (section) {
                    // Activate appropriate tab
                    if (sectionClass === 'q-a') {
                        var qaTab = document.querySelector('[data-target=\"#herlan-tab-qa\"]');
                        if (qaTab) {
                            qaTab.click();
                        }
                    }

                    // Scroll to section
                    setTimeout(function() {
                        section.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    }, sectionClass === 'q-a' ? 100 : 0);
                }
            }
        })(); (function () {
        var SCOPE = '#content, .site-content, #primary, main';

        function inScope(img) { return img.closest && img.closest(SCOPE) && !img.closest('.pswp'); }

        function mark(img) {
            if (!inScope(img)) { return; }

            if (!img.complete) {
                img.classList.add('herlan-img-pending');
                return;
            }

            // Already finished - and without a picture: it failed before this script ran. (SVGs without a
            // size also report 0 wide, so they are left alone.)
            var src = img.getAttribute('src') || '';
            if (src && img.naturalWidth === 0 && !/\.svg(\?|$)|^data:image\/svg/i.test(src)) {
                img.classList.add('herlan-img-error');
            }
        }

        // Images already in the page and not loaded yet.
        [].forEach.call(document.images, mark);

        // Images that finish (or fail) later, including ones added by scripts: load and error do not
        // bubble, so they are caught on the way down.
        document.addEventListener('load', function (event) {
            var img = event.target;
            if (img && img.tagName === 'IMG') { img.classList.remove('herlan-img-pending', 'herlan-img-error'); }
        }, true);

        document.addEventListener('error', function (event) {
            var img = event.target;
            if (img && img.tagName === 'IMG' && inScope(img)) {
                img.classList.remove('herlan-img-pending');
                img.classList.add('herlan-img-error');
            }
        }, true);

        // Images added after this ran (sliders, load more, AJAX): mark the ones that are not ready.
        if (window.MutationObserver) {
            new MutationObserver(function (records) {
                records.forEach(function (record) {
                    [].forEach.call(record.addedNodes, function (node) {
                        if (node.nodeType !== 1) { return; }
                        if (node.tagName === 'IMG') { mark(node); }
                        else if (node.querySelectorAll) { [].forEach.call(node.querySelectorAll('img'), mark); }
                    });
                });
            }).observe(document.body, { childList: true, subtree: true });
        }
