//# sourceURL=herlan-review-script-js-extra (function($) {
    'use strict';

    if (!$) {
        return;
    }

    $(function() {
        window.setTimeout(function() {
        if (window.herlanReviewsFiltersActive || !window.herlan || !$('.herlan-product-reviews').length) {
            return;
        }

        function showReviewError() {
            if (window.Toastify) {
                Toastify({
                    text: 'Failed to load reviews. Please try again.',
                    duration: 3000,
                    close: true,
                    gravity: 'bottom',
                    position: 'left',
                    stopOnFocus: true,
                    style: {
                        background: '#f87171',
                        borderRadius: '8px',
                        padding: '16px 24px',
                        fontSize: '16px',
                        fontWeight: '500'
                    }
                }).showToast();
            } else if (window.console) {
                console.error('Failed to load reviews.');
            }
        }

        function loadReviews($reviewsContainer, offset, replaceList) {
            var $reviewsList = $reviewsContainer.find('.herlan-product-reviews__list');
            var $footer = $reviewsContainer.find('.herlan-product-reviews__footer');
            var $btn = $footer.find('.herlan-load-more-reviews-btn');
            var productId = $reviewsContainer.data('product-id');
            var filterProductId = $reviewsContainer.find('.herlan-review-filter--product').val() || '';
            var sortBy = $reviewsContainer.find('.herlan-review-filter--sort').val() || '';
            var ratingFilter = $reviewsContainer.find('.herlan-review-filter--rating').val() || '';

            if (!$reviewsList.length || !productId) {
                return;
            }

            if (!$footer.length) {
                $footer = $('<div class="herlan-product-reviews__footer"><button type="button" class="herlan-load-more-reviews-btn">Load More</button></div>');
                $reviewsContainer.append($footer);
                $btn = $footer.find('.herlan-load-more-reviews-btn');
            }

            if (replaceList) {
                $reviewsList.addClass('herlan-product-reviews__list--loading');
            }

            $btn.prop('disabled', true).text('Loading...');

            $.ajax({
                url: herlan.ajax_url,
                type: 'POST',
                data: {
                    action: 'herlan_load_more_reviews',
                    nonce: herlan.nonce,
                    product_id: productId,
                    offset: offset,
                    filter_product_id: filterProductId,
                    sort_by: sortBy,
                    rating_filter: ratingFilter
                },
                success: function(response) {
                    if (!response.success) {
                        $btn.prop('disabled', false).text('Load More');
                        return;
                    }

                    var loadedCount = parseInt(response.data.loaded_count || 0, 10);
                    var totalReviews = parseInt(response.data.total_reviews || 0, 10);

                    if (replaceList) {
                        $reviewsList.empty();
                    }

                    if (response.data.html) {
                        $reviewsList.append(response.data.html);
                    } else if (replaceList) {
                        $reviewsList.append('<div class="herlan-no-reviews">No reviews found.</div>');
                    }

                    $reviewsContainer.data('loaded', offset + loadedCount);
                    $reviewsContainer.attr('data-loaded', offset + loadedCount);

                    if (replaceList || totalReviews > 0) {
                        $reviewsContainer.attr('data-total-reviews', totalReviews);
                        $reviewsContainer.find('.herlan-product-reviews__title').text('Product Reviews (' + totalReviews + ')');
                    }

                    if (!response.data.has_more || loadedCount === 0) {
                        $footer.hide();
                    } else {
                        $footer.show();
                        $btn.prop('disabled', false).text('Load More');
                    }
                },
                error: function() {
                    $btn.prop('disabled', false).text('Load More');
                    showReviewError();
                },
                complete: function() {
                    if (replaceList) {
                        $reviewsList.removeClass('herlan-product-reviews__list--loading');
                    }
                }
            });
        }

        $(document)
            .off('click', '.herlan-load-more-reviews-btn')
            .on('click.herlanReviewFilterFallback', '.herlan-load-more-reviews-btn', function() {
                var $reviewsContainer = $(this).closest('.herlan-product-reviews');
                var currentLoaded = parseInt($reviewsContainer.data('loaded'), 10);

                if (isNaN(currentLoaded)) {
                    currentLoaded = $reviewsContainer.find('.herlan-review-item').length;
                }

                loadReviews($reviewsContainer, currentLoaded, false);
            })
            .off('change', '.herlan-review-filter')
            .on('change.herlanReviewFilterFallback', '.herlan-review-filter', function() {
                loadReviews($(this).closest('.herlan-product-reviews'), 0, true);
            });

        window.herlanReviewsFiltersActive = true;
        }, 0);
    });
})(window.jQuery);
