//# sourceURL=master-script-js-before (function(){
    if (!('IntersectionObserver' in window)) return;
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    var selectors = [
        '.herlan-home-slider-v2-wrapper',
        '.herlan-product-groups-section',
        '.herlan-home-product-categories-container',
        '.herlan-product-tag-container',
        '.custom-tags-list-home',
        '.home-page-campaign-shortcuts',
        '.herlan-common-page-header',
        '.herlan-home-banner-wrapper'
    ];
    var targets = document.querySelectorAll(selectors.join(','));
    if (!targets.length) return;

    var io = new IntersectionObserver(function(entries){
        entries.forEach(function(entry){
            if (entry.isIntersecting) {
                entry.target.classList.add('is-visible');
                io.unobserve(entry.target);
            }
        });
    }, { threshold: 0.08, rootMargin: '0px 0px -40px 0px' });

    var viewportHeight = window.innerHeight || document.documentElement.clientHeight;
    targets.forEach(function(el){
        if (el.getBoundingClientRect().top < viewportHeight) {
            // Keep initially visible homepage content paintable immediately.
            // Hiding it until IntersectionObserver runs can delay LCP on mobile.
            el.classList.add('herlan-reveal', 'is-visible');
            return;
        }

        el.classList.add('herlan-reveal');
        io.observe(el);
    });
})();
(function () {
    if (!window.matchMedia || !window.matchMedia('(max-width: 992px)').matches) {
        return;
    }

    function prepareMobileProductCards(root) {
        var scope = root && root.querySelectorAll ? root : document;
        scope.querySelectorAll('.shoptimizer-plp-carousel-container').forEach(function (carousel) {
            var wrapper = carousel.querySelector('.shoptimizer-plp-image-wrapper');
            if (!wrapper) {
                return;
            }

            // Reorder only - featured image first, then every gallery image
            // in its existing order. Products can have any number of gallery
            // photos now, so nothing beyond the featured image is removed
            // here anymore (it used to cap every card at 2 images total).
            var featured = wrapper.querySelector('img:not(.gallery-image)');
            if (featured && wrapper.firstElementChild !== featured) {
                wrapper.insertBefore(featured, wrapper.firstElementChild);
            }

            wrapper.querySelectorAll('img.gallery-image').forEach(function (img) {
                wrapper.appendChild(img);
            });

            carousel.dataset.currentIndex = '0';
            wrapper.style.transform = 'translateX(0%)';
            wrapper.style.transition = '';

            wrapper.querySelectorAll('img').forEach(function (img) {
                img.decoding = 'async';

                var sizes = img.getAttribute('sizes');
                if (sizes && sizes.indexOf('auto') !== -1) {
                    img.setAttribute('sizes', '(max-width: 767px) 40vw, 30vw');
                }

