(function ($) {
    if (!window.herlanBdLocations) return;
    var DATA = window.herlanBdLocations;

    function fillSelect($select, options, placeholder) {
        var current = $select.val();
        var html = '<option value="">' + placeholder + '</option>';
        options.forEach(function (opt) {
            html += '<option value="' + opt.value.replace(/"/g, '&quot;') + '">' + opt.label + '</option>';
        });
        $select.html(html);
        if (current && $select.find('option[value="' + current.replace(/"/g, '\\"') + '"]').length) {
            $select.val(current);
        }
        // Refresh select2/selectWoo's own rendered copy, if this select is
        // enhanced - otherwise the dropdown keeps showing stale options.
        if ($select.data('select2')) {
            $select.trigger('change.select2');
        }
        $select.trigger('change');
    }

    // The customer picks the District (city) and the Thana (area); the Division follows from the District, so
    // the list holds every district and nothing is filtered by a division chosen first.
    function districtsFor() {
        var list = [];
        Object.keys(DATA.divisions).forEach(function (slug) {
            var districts = DATA.divisions[slug].districts;
            Object.keys(districts).forEach(function (code) {
                list.push({ value: code, label: districts[code].name });
            });
        });
        return list.sort(function (a, b) { return a.label.localeCompare(b.label); });
    }

    function divisionOf(districtCode) {
        return (districtCode && DATA.districtToDivision[districtCode]) || '';
    }

    function setDivision(p, districtCode) {
        var $division = $('#' + p + 'division');
        var slug = divisionOf(districtCode);
        if (!$division.length || $division.val() === slug) return slug;
        $division.val(slug);
        if ($division.data('select2')) $division.trigger('change.select2');
        return slug;
    }

    function districtBelongsTo(divisionSlug, districtCode) {
        var division = DATA.divisions[divisionSlug];
        return !!(division && division.districts[districtCode]);
    }

    function thanasFor(divisionSlug, districtCode) {
        var division = DATA.divisions[divisionSlug];
        var district = division && division.districts[districtCode];
        if (!district) return [];
        return district.thanas.map(function (name) {
            return { value: name, label: name };
        });
    }

    function postcodeFor(divisionSlug, districtCode, thanaName) {
        var division = DATA.divisions[divisionSlug];
        var district = division && division.districts[districtCode];
        if (!district) return '';
        return district.postcodes[thanaName] || '';
    }

    function districtNameFor(divisionSlug, districtCode) {
        var division = DATA.divisions[divisionSlug];
        var district = division && division.districts[districtCode];
        return district ? district.name : '';
    }

    function prefix(id) {
        return id.indexOf('billing_') === 0 ? 'billing_' : 'shipping_';
    }

    // Postcode field itself stays hidden from the customer (this theme's
    // own Bangladesh checkout customisation already sets it optional and
    // form-row-hidden) - this writes into it so WooCommerce's native
    // shipping-zone postcode matching can target a mapped thana. When a
    // thana has no mapping, the value must be cleared: keeping the previous
    // thana's postcode would silently apply that previous thana's zone/rate.
    function syncThanaPostcode(prefix, postcode) {
        var $postcode = $('#' + prefix + 'postcode');
        if (!$postcode.length) return;

        var next = postcode || '';
        if ($postcode.val() === next) return;

        $postcode.val(next).trigger('change');
    }

    // City is also a hidden/optional field on this checkout (see
    // woocommerce-checkout.php), left blank by the customer since Division/
    // District/Thana already capture the address. Auto-filling it from the
    // most specific level picked so far - Thana, falling back to District
    // when no Thana is chosen yet - means the field is never just empty:
    // WooCommerce's formatted address, admin order screen, and any code
    // reading billing_city (including Meta Pixel's own Automatic Advanced
    // Matching, which reads whatever is actually in the DOM's form fields)
    // get a real value instead of nothing.
    function syncThanaCity(prefix, city) {
        var $city = $('#' + prefix + 'city');
        if (!$city.length) return;

        var next = city || '';
        if ($city.val() === next) return;

        $city.val(next).trigger('change');
    }

    function onThanaChange(e) {
        var p = prefix(e.target.id);
        var thanaName = $(e.target).val();
        var divisionSlug = $('#' + p + 'division').val();
        var districtCode = $('#' + p + 'state').val();
        var postcode = thanaName ? postcodeFor(divisionSlug, districtCode, thanaName) : '';
        var city = thanaName || districtNameFor(divisionSlug, districtCode);

        syncThanaPostcode(p, postcode);
        syncThanaCity(p, city);
    }

    function onDistrictChange(e) {
        var p = prefix(e.target.id);
        var districtCode = $(e.target).val();

        // The division always follows the district (and is cleared with it).
        var divisionSlug = setDivision(p, districtCode);

        var $thana = $('#' + p + 'thana');
        fillSelect($thana, districtCode ? thanasFor(divisionSlug, districtCode) : [], 'Select Area');
        syncThanaPostcode(p, '');
        syncThanaCity(p, districtCode ? districtNameFor(divisionSlug, districtCode) : '');
    }

    // Moves a field only when it is not already right after its anchor. This runs after every checkout refresh;
    // re-inserting a field that is already in place still detaches it, which blurs the select the customer has
    // just used and makes the page jump on a phone.
    function placeAfter($el, $anchor) {
        if ($anchor.next()[0] !== $el[0]) $el.insertAfter($anchor);
    }

    function arrangeAddressFields(p) {
        if (p === 'billing' && $('form.checkout').length) {
            var $previous = null;
            var fields = ['first_name', 'phone', 'division', 'state', 'thana', 'address_1', 'email'];
            var priorities = [10, 20, 40, 50, 60, 70, 80];
            fields.forEach(function (name, index) {
                var $field = $('#billing_' + name + '_field');
                if (!$field.length) return;
                // Update jQuery's cache too: address-i18n sorts using .data().
                $field.attr('data-priority', priorities[index]).data('priority', priorities[index]);
                if ($previous) placeAfter($field, $previous);
                $previous = $field;
            });
            return;
        }
        var $division = $('#' + p + '_division_field');
        var $district = $('#' + p + '_state_field');
        var $thana = $('#' + p + '_thana_field');
        var $address = $('#' + p + '_address_1_field');

        if (!$division.length || !$district.length || !$thana.length || !$address.length) return;

        if ($division.next()[0] !== $district[0]) $division.insertBefore($district);
        placeAfter($thana, $district);
        var $area = $('#' + p + '_address_2_field');
        if (p === 'billing' && $area.length && !$area.hasClass('form-row-hidden')) {
            placeAfter($area, $thana);
            placeAfter($address, $area);
        } else {
            placeAfter($address, $thana);
        }
    }

    $(document).on('change', '#billing_state, #shipping_state', onDistrictChange);
    $(document).on('change', '#billing_thana, #shipping_thana', onThanaChange);
    $(document.body).on('updated_checkout', function () {
        arrangeAddressFields('billing');
    });

    // Re-applies Division's district list + District's thana list from our
    // own data, re-selecting whatever was already chosen. Used both on
    // first load and to repair WooCommerce's own country->state handling
    // (see the country_to_state_changed listener below) stomping on the
    // District field.
    function applyCascade(p) {
        var $district = $('#' + p + '_state');
        if (!$district.length) return;

        var districtVal = $district.val();
        // A saved or autofilled value that is not one of our districts cannot be used.
        if (districtVal && !divisionOf(districtVal)) {
            districtVal = '';
        }

        fillSelect($district, districtsFor(), 'Select City');
        $district.val(districtVal);

        var divisionVal = setDivision(p + '_', districtVal);

        var $thana = $('#' + p + '_thana');
        var thanaVal = $thana.data('presetValue') || $thana.val();
        if (divisionVal && districtVal) {
            fillSelect($thana, thanasFor(divisionVal, districtVal), 'Select Area');
            if (thanaVal) {
                $thana.val(thanaVal);
                var postcode = postcodeFor(divisionVal, districtVal, thanaVal);
                syncThanaPostcode(p + '_', postcode);
                syncThanaCity(p + '_', thanaVal);
            } else {
                syncThanaPostcode(p + '_', '');
                syncThanaCity(p + '_', districtNameFor(divisionVal, districtVal));
            }
        } else {
            syncThanaPostcode(p + '_', '');
            syncThanaCity(p + '_', '');
        }
    }

    // On first load (e.g. a logged-in customer's saved address already
    // filled these fields server-side), run the cascade once so District
    // and Thana's option lists match whatever Division/District came
    // pre-selected, instead of showing empty dropdowns until the
    // customer touches something.
    $(function () {
        ['billing', 'shipping'].forEach(function (p) {
            applyCascade(p);
            arrangeAddressFields(p);
        });
    });

    // WooCommerce core's own country-select script (assets/js/frontend/
    // country-select.js) unconditionally re-syncs every "state" field to
    // the currently selected country once its i18n data finishes loading
    // (the wc_address_i18n_ready -> refresh -> country_to_state_changed
    // chain), rebuilding #billing_state/#shipping_state from WooCommerce's
    // own raw, unfiltered district list - wiping out the Division-filtered
    // list this feature puts there. Since this site only ever ships within
    // Bangladesh (country never actually changes), just repair our fields
    // immediately after that happens rather than fighting core's loading
    // order.
    $(document.body).on('country_to_state_changed', function () {
        ['billing', 'shipping'].forEach(function (p) {
            applyCascade(p);
            arrangeAddressFields(p);
        });
    });

    // This checkout shows one "Full Name" field (billing_first_name /
    // shipping_first_name, relabeled - see woocommerce-checkout.php) and
    // keeps the real last_name field hidden and optional, so it's almost
    // always empty: WooCommerce order data, the admin order screen, and
    // Meta Pixel's Automatic Advanced Matching (which reads whatever is
    // actually sitting in the page's form fields) all end up with no
    // surname at all. This only ever writes the hidden last_name field -
    // the visible Full Name input the customer is typing into is never
    // touched - so what they see never changes. The authoritative split
    // that actually reshapes billing_first_name/billing_last_name for the
    // order itself happens server-side, in
    // herlan_bd_split_full_name_for_checkout() below; this is purely so a
    // value is already present in the hidden field while the customer is
    // still on the checkout page.
    function splitFullName(fullName) {
        var trimmed = String(fullName || '').trim().replace(/\s+/g, ' ');
        if (!trimmed) return { first: '', last: '' };

        var parts = trimmed.split(' ');
        if (parts.length === 1) return { first: parts[0], last: '' };

        return { first: parts[0], last: parts.slice(1).join(' ') };
    }

    $(document).on('input', '#billing_first_name, #shipping_first_name', function () {
        var p = prefix(this.id);
        var $lastName = $('#' + p + 'last_name');
        if (!$lastName.length) return;

        $lastName.val(splitFullName($(this).val()).last);
    });
})(jQuery);
