//# sourceURL=jquery-dgwt-wcas-js-extra .hmenu-location { box-sizing: border-box; margin: 10px 16px 8px; padding: 10px 12px; border: 1px solid #eceef2; border-radius: 12px; background: #fff; box-shadow: 0 2px 8px rgba(20, 24, 32, .04); font-size: 13px; line-height: 1.4; color: #222; }
        .hmenu-location[hidden] { display: none; }
        .hmenu-loc__head { display: flex; align-items: center; gap: 8px; width: 100%; padding: 0; background: none; border: 0; text-align: left; color: inherit; font: inherit; cursor: pointer; }
        .hmenu-loc__pin { flex: none; width: 30px; height: 30px; border-radius: 9px; background: #fff0f1; color: #e60023; display: flex; align-items: center; justify-content: center; }
        .hmenu-loc__pin svg { width: 16px; height: 16px; }
        .hmenu-loc__text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
        .hmenu-loc__label { font-size: 11px; line-height: 1.3; color: #6b7280; }
        .hmenu-loc__place { overflow: hidden; font-size: 14px; font-weight: 650; line-height: 1.3; text-overflow: ellipsis; white-space: nowrap; }
        .hmenu-loc__change { flex: none; padding: 4px 10px; border: 1px solid #f5d7da; border-radius: 999px; background: #fff8f8; font-size: 12px; font-weight: 600; line-height: 1.3; color: #d71920; }
        .hmenu-loc__status { margin: 6px 0 0; font-size: 12px; color: #6b7280; }
        .hmenu-loc__status.is-error { color: #b32d2e; }
        /* the delivery options: plain rows under the location line, a divider between them, none above the first (they were cards inside the card) */
        .hmenu-location .hmenu-loc__rates { list-style: none; margin: 6px 0 0 !important; padding: 0 !important; display: block; border-top: 0; }
        .hmenu-location .hmenu-loc__rate { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin: 0; padding: 8px 0; background: none; border: 0; border-bottom: 1px solid #f0f1f4; border-radius: 0; }
        .hmenu-location .hmenu-loc__rate:last-child { border-bottom: 0; padding-bottom: 2px; }
        .hmenu-loc__rate.is-off { opacity: .55; }
        .hmenu-loc__rate-name { font-size: 13px; font-weight: 600; line-height: 1.3; }
        .hmenu-loc__rate-note { display: block; margin-top: 1px; font-size: 11px; font-weight: 400; line-height: 1.3; color: #6b7280; }
        .hmenu-loc__rate-cost { flex: none; font-size: 14px; font-weight: 700; }
        .hmenu-loc__note { margin: 4px 0 0; font-size: 11px; color: #687080; }
        .hmenu-loc__picker { display: flex; flex-direction: column; gap: 8px; margin-top: 10px; }
        .hmenu-loc__picker select { width: 100%; min-height: 40px; padding: 0 10px; border: 1px solid #d5d8dc; border-radius: 8px; background: #fff; font-size: 14px; color: #222; }
        .hmenu-loc__go { min-height: 40px; border: 0; border-radius: 8px; background: #111; color: #fff; font-size: 14px; font-weight: 600; cursor: pointer; }
        .hmenu-loc__go[disabled] { opacity: .5; }
        .hmenu-loc__link { align-self: flex-start; padding: 0; background: none; border: 0; font-size: 12px; font-weight: 600; color: #e60023; cursor: pointer; }
        body.mobile-toggled .col-full-nav .main-navigation ul#menu-site-nav.menu > li { box-sizing: border-box; margin: 10px 16px 0 !important; overflow: hidden; border: 1px solid #eceef2 !important; border-radius: 10px; background: #fff; }
        body.mobile-toggled .col-full-nav .main-navigation ul#menu-site-nav.menu > li.menu-item-offers { margin-top: 12px !important; }
        body.mobile-toggled .col-full-nav .main-navigation ul#menu-site-nav.menu > li > a { gap: 10px; min-height: 48px; padding: 8px 12px !important; }
        .hmenu-menu__icon { display: inline-flex; flex: 0 0 30px; width: 30px; height: 30px; align-items: center; justify-content: center; border-radius: 9px; background: #fff0f1; color: #df1d27; }
        .hmenu-menu__icon svg { display: block; width: 17px; height: 17px; }
