        var CFG = {"cookie":"herlan_loc","quote":"\/?wc-ajax=herlan_delivery_quote","strings":{"title":"Delivery location","prompt":"Check delivery charge","detect":"Use my location","choose":"Choose area","change":"Change","finding":"Finding your location\u2026","lookup":"Checking delivery charge\u2026","denied":"We could not get your location. Please choose your area.","nomatch":"We could not tell your area from your location. Please choose it.","division":"Division","district":"City","thana":"Area","show":"Show delivery charge","pickThana":"Choose your thana for the exact charge","unavailable":"We do not deliver to this area yet.","unavailableNow":"Not available right now","freeOver":"Free delivery over %s","basedOnCart":"Charge for the items in your cart","failed":"Could not check the charge. Please try again.","none":"Select"}};
