        var PIN = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 21s7-6.2 7-11.5A7 7 0 0 0 5 9.5C5 14.8 12 21 12 21Z"/><circle cx="12" cy="9.5" r="2.5"/></svg>';

        /* ── matching a reverse-geocoded address to the site's own list (same rules as the checkout map) ── */
        function normalise(v) {
            return String(v || '').toLowerCase()
                .replace(/\b(upazila|thana|subdistrict|municipality|pourashava|citycorporation|city|union|ward)\b/g, '')
                .replace(/[^a-z0-9]/g, '');
        }
        function namesMatch(a, b) {
            a = normalise(a); b = normalise(b);
            if (!a || !b) { return false; }
            if (a === b) { return true; }
            var shorter = a.length < b.length ? a : b, longer = a.length < b.length ? b : a;
            return shorter.length >= 4 && longer.indexOf(shorter) !== -1;
        }
        function matchLocation(address, displayName) {
            var db = data();
            if (!db) { return null; }
            var districtCandidates = [address.state_district, address.county, address.district, address.city, address.town, address.municipality, address.city_district].filter(Boolean);
            var districtCodes = [address['ISO3166-2-lvl5'], address['ISO3166-2-lvl6'], address['ISO3166-2-lvl7']].filter(Boolean).map(function (c) { return String(c).toUpperCase(); });
            var found = [];
            Object.keys(db.divisions).forEach(function (dv) {
                var districts = db.divisions[dv].districts || {};
                Object.keys(districts).forEach(function (code) {
                    var hit = districtCodes.indexOf(String(code).toUpperCase()) !== -1 || districtCandidates.some(function (c) { return namesMatch(districts[code].name, c); });
                    if (hit) { found.push({ division: dv, district: code, info: districts[code] }); }
                });
            });
            if (found.length !== 1) { return null; }          // never guess between districts
            var match = found[0], info = match.info;
            var postcode = String(address.postcode || '').replace(/\D/g, '');
            var aliases = info.postcodeAliases || {};
            var byCode = Object.keys(aliases).filter(function (name) {
                var codes = Array.isArray(aliases[name]) ? aliases[name] : [aliases[name]];
                return postcode && codes.some(function (c) { return String(c || '').replace(/\D/g, '') === postcode; });
            });
            var thana = byCode.length === 1 ? byCode[0] : '';
            if (!thana) {
                var cands = [address.subdistrict, address.city_district, address.borough, address.neighbourhood, address.suburb, address.quarter, address.residential, address.locality, address.village, address.hamlet, address.municipality].filter(Boolean);
                if (displayName) { cands = cands.concat(String(displayName).split(',')); }
                var scored = (info.thanas || []).map(function (name) {
                    var score = cands.reduce(function (best, c, i) {
                        if (!namesMatch(name, c)) { return best; }
                        return Math.max(best, (normalise(name) === normalise(c) ? 100 : 50) - Math.min(i, 20));
                    }, 0);
                    return { name: name, score: score };
                }).filter(function (x) { return x.score > 0; }).sort(function (a, b) { return b.score - a.score; });
                thana = scored.length && (!scored[1] || scored[0].score > scored[1].score) ? scored[0].name : '';
            }
